window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-52b1e9069b69454a"]={"versions": [{"id": "FIG-52b1e9069b69454a", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Initialisierung und Referenzzeit-Initialisierung (<code>V2xM_Init - Time initialization</code>) im AUTOSAR Classic Platform Kontext. Dargestellt ist das Zusammenspiel der V2X-Stack-Basissoftwaremodule (<code>V2xM</code>, <code>V2xGn</code>, <code>V2xBtp</code>, <code>V2xFac</code>) unter der Initialisierungssteuerung des ECU State Managers (<code>EcuM</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\"><li><code>EcuM</code>: ECU State Manager (koordinierende Instanz mit Endlosschleifen-/Ablauf-Symbol)\n</li><li><code>V2xM</code>: V2X Management\n</li><li><code>V2xGn</code>: V2X GeoNetworking\n</li><li><code>V2xBtp</code>: V2X Basic Transport Protocol\n</li><li><code>V2xFac</code>: V2X Facilities\n</li></ul>\n<p class=\"fig-p\">Schnittstellen / Aufrufe:</p>\n<ul class=\"fig-list\"><li><code>V2xM_Init(const V2xM_ConfigType*)</code>: Synchroner Initialisierungsaufruf von <code>EcuM</code> an <code>V2xM</code>.\n</li><li><code>V2xGn_Init()</code>: Parameterloser synchroner Initialisierungsaufruf von <code>EcuM</code> an <code>V2xGn</code>.\n</li><li><code>V2xFac_Init()</code>: Parameterloser synchroner Initialisierungsaufruf von <code>EcuM</code> an <code>V2xFac</code>.\n</li><li><code>V2xBtp_Init()</code>: Parameterloser synchroner Initialisierungsaufruf von <code>EcuM</code> an <code>V2xBtp</code>.\n</li><li><code>V2xM_GetRefTimePtr(Std_ReturnType, uint32** const)</code>: Synchroner Abfrageaufruf von <code>V2xGn</code> und <code>V2xFac</code> an <code>V2xM</code> zur Bereitstellung des Referenzzeit-Zeigers.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequenzablauf der Initialisierung:</p>\n<ol class=\"fig-list\"><li><code>EcuM</code> ruft synchron <code>V2xM_Init(const V2xM_ConfigType*)</code> auf, wodurch <code>V2xM</code> initialisiert wird.\n</li><li><code>EcuM</code> ruft anschließend synchron <code>V2xGn_Init()</code> auf.\n</li><li>Im Verlauf der Initialisierung von <code>V2xGn</code> ruft dieses synchron <code>V2xM_GetRefTimePtr(Std_ReturnType, uint32** const)</code> auf, um den Zeiger auf die Referenzzeit von <code>V2xM</code> zu beziehen.\n</li><li>Nach Abschluss der <code>V2xGn</code>-Initialisierung ruft <code>EcuM</code> synchron <code>V2xFac_Init()</code> auf.\n</li><li>Im Verlauf der Initialisierung von <code>V2xFac</code> ruft dieses synchron <code>V2xM_GetRefTimePtr(Std_ReturnType, uint32** const)</code> auf.\n</li><li>Nach Abschluss der <code>V2xFac</code>-Initialisierung stößt <code>EcuM</code> die Initialisierung des Transportprotokolls über <code>V2xBtp_Init()</code> an.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die BSW-Initialisierungssequenz und die Modulkopplung im V2X-Stack:</p>\n<ul class=\"fig-list\"><li><code>V2xM</code> muss vor den abhängigen V2X-Modulen (<code>V2xGn</code>, <code>V2xFac</code>) initialisiert sein, da diese während ihrer Initialisierung synchron die Referenzzeit über <code>V2xM_GetRefTimePtr</code> anfordern.\n</li><li>Die Initialisierungsreihenfolge durch <code>EcuM</code> (<code>V2xM</code> vor <code>V2xGn</code>, <code>V2xFac</code> und <code>V2xBtp</code>) ist einzuhalten.\n</li><li>Implementierer müssen sicherstellen, dass die Signaturen der Init-Funktionen und der Referenzzeit-Abfrage exakt den AUTOSAR-V2X-Spezifikationen entsprechen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e9e4b351be752ca4", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Initialisierung und Referenzzeit-Initialisierung (<code>V2xM_Init - Time initialization</code>) im AUTOSAR Classic Platform Kontext. Dargestellt ist das Zusammenspiel der V2X-Stack-Basissoftwaremodule (<code>V2xM</code>, <code>V2xGn</code>, <code>V2xBtp</code>, <code>V2xFac</code>) unter der Initialisierungssteuerung des ECU State Managers (<code>EcuM</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\"><li><code>EcuM</code>: ECU State Manager (koordinierende Instanz mit Endlosschleifen-/Ablauf-Symbol)\n</li><li><code>V2xM</code>: V2X Management\n</li><li><code>V2xGn</code>: V2X GeoNetworking\n</li><li><code>V2xBtp</code>: V2X Basic Transport Protocol\n</li><li><code>V2xFac</code>: V2X Facilities\n</li></ul>\n<p class=\"fig-p\">Schnittstellen / Aufrufe:</p>\n<ul class=\"fig-list\"><li><code>V2xM_Init(const void *)</code>: Synchroner Initialisierungsaufruf von <code>EcuM</code> an <code>V2xM</code> mit generischem Zeiger.\n</li><li><code>V2xGn_Init(const void *)</code>: Synchroner Initialisierungsaufruf von <code>EcuM</code> an <code>V2xGn</code> mit generischem Zeiger.\n</li><li><code>V2xFac_Init(const void *)</code>: Synchroner Initialisierungsaufruf von <code>EcuM</code> an <code>V2xFac</code> mit generischem Zeiger.\n</li><li><code>V2xBtp_Init(void*)</code>: Synchroner Initialisierungsaufruf von <code>EcuM</code> an <code>V2xBtp</code> mit generischem Zeiger.\n</li><li><code>V2xM_GetRefTimePtr(Std_ReturnType, uint32** const*)</code>: Synchroner Abfrageaufruf von <code>V2xGn</code> und <code>V2xFac</code> an <code>V2xM</code> zur Bereitstellung des Referenzzeit-Zeigers.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequenzablauf der Initialisierung:</p>\n<ol class=\"fig-list\"><li><code>EcuM</code> ruft synchron <code>V2xM_Init(const void *)</code> auf, wodurch <code>V2xM</code> initialisiert wird.\n</li><li><code>EcuM</code> ruft anschließend synchron <code>V2xGn_Init(const void *)</code> auf.\n</li><li>Im Verlauf der Initialisierung von <code>V2xGn</code> ruft dieses synchron <code>V2xM_GetRefTimePtr(Std_ReturnType, uint32** const*)</code> auf, um den Zeiger auf die Referenzzeit von <code>V2xM</code> zu beziehen.\n</li><li>Nach Abschluss der <code>V2xGn</code>-Initialisierung ruft <code>EcuM</code> synchron <code>V2xFac_Init(const void *)</code> auf.\n</li><li>Im Verlauf der Initialisierung von <code>V2xFac</code> ruft dieses synchron <code>V2xM_GetRefTimePtr(Std_ReturnType, uint32** const*)</code> auf.\n</li><li>Nach Abschluss der <code>V2xFac</code>-Initialisierung stößt <code>EcuM</code> die Initialisierung des Transportprotokolls über <code>V2xBtp_Init(void*)</code> an.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die BSW-Initialisierungssequenz und die Modulkopplung im V2X-Stack:</p>\n<ul class=\"fig-list\"><li><code>V2xM</code> muss vor den abhängigen V2X-Modulen (<code>V2xGn</code>, <code>V2xFac</code>) initialisiert sein, da diese während ihrer Initialisierung synchron die Referenzzeit über <code>V2xM_GetRefTimePtr</code> anfordern.\n</li><li>Die Initialisierungsreihenfolge durch <code>EcuM</code> (<code>V2xM</code> vor <code>V2xGn</code>, <code>V2xFac</code> und <code>V2xBtp</code>) ist einzuhalten.\n</li><li>Implementierer müssen sicherstellen, dass die Signaturen der Init-Funktionen generische Konfigurationszeiger (<code>const void *</code> bzw. <code>void*</code>) verwenden und der Abruf der Referenzzeit der Signatur <code>V2xM_GetRefTimePtr(Std_ReturnType, uint32** const*)</code> entspricht.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-85bc6c5cfdb31b0d", "releases": ["R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Initialisierung und Referenzzeit-Initialisierung (<code>V2xM_Init - Time initialization</code>) im AUTOSAR Classic Platform Kontext. Dargestellt ist das Zusammenspiel der V2X-Stack-Basissoftwaremodule (<code>V2xM</code>, <code>V2xGn</code>, <code>V2xBtp</code>, <code>V2xFac</code>) unter der Initialisierungssteuerung des ECU State Managers (<code>EcuM</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\"><li><code>EcuM</code>: ECU State Manager (koordinierende Instanz mit Endlosschleifen-/Ablauf-Symbol)\n</li><li><code>V2xM</code>: V2X Management\n</li><li><code>V2xGn</code>: V2X GeoNetworking\n</li><li><code>V2xBtp</code>: V2X Basic Transport Protocol\n</li><li><code>V2xFac</code>: V2X Facilities\n</li></ul>\n<p class=\"fig-p\">Schnittstellen / Aufrufe:</p>\n<ul class=\"fig-list\"><li><code>V2xM_Init(const void *)</code>: Synchroner Initialisierungsaufruf von <code>EcuM</code> an <code>V2xM</code> mit generischem Zeiger.\n</li><li><code>V2xGn_Init(const void *)</code>: Synchroner Initialisierungsaufruf von <code>EcuM</code> an <code>V2xGn</code> mit generischem Zeiger.\n</li><li><code>V2xFac_Init(const void *)</code>: Synchroner Initialisierungsaufruf von <code>EcuM</code> an <code>V2xFac</code> mit generischem Zeiger.\n</li><li><code>V2xBtp_Init(void*)</code>: Synchroner Initialisierungsaufruf von <code>EcuM</code> an <code>V2xBtp</code> mit generischem Zeiger.\n</li><li><code>V2xM_GetRefTimePtr(Std_ReturnType, uint32** const*)</code>: Synchroner Abfrageaufruf von <code>V2xGn</code> und <code>V2xFac</code> an <code>V2xM</code> zur Bereitstellung des Referenzzeit-Zeigers.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequenzablauf der Initialisierung:</p>\n<ol class=\"fig-list\"><li><code>EcuM</code> ruft synchron <code>V2xM_Init(const void *)</code> auf, wodurch <code>V2xM</code> initialisiert wird.\n</li><li><code>EcuM</code> ruft anschließend synchron <code>V2xGn_Init(const void *)</code> auf.\n</li><li>Im Verlauf der Initialisierung von <code>V2xGn</code> ruft dieses synchron <code>V2xM_GetRefTimePtr(Std_ReturnType, uint32** const*)</code> auf, um den Zeiger auf die Referenzzeit von <code>V2xM</code> zu beziehen.\n</li><li>Nach Abschluss der <code>V2xGn</code>-Initialisierung ruft <code>EcuM</code> synchron <code>V2xFac_Init(const void *)</code> auf.\n</li><li>Im Verlauf der Initialisierung von <code>V2xFac</code> ruft dieses synchron <code>V2xM_GetRefTimePtr(Std_ReturnType, uint32** const*)</code> auf.\n</li><li>Nach Abschluss der <code>V2xFac</code>-Initialisierung stößt <code>EcuM</code> die Initialisierung des Transportprotokolls über <code>V2xBtp_Init(void*)</code> an.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die BSW-Initialisierungssequenz und die Modulkopplung im V2X-Stack:</p>\n<ul class=\"fig-list\"><li><code>V2xM</code> muss vor den abhängigen V2X-Modulen (<code>V2xGn</code>, <code>V2xFac</code>) initialisiert sein, da diese während ihrer Initialisierung synchron die Referenzzeit über <code>V2xM_GetRefTimePtr</code> anfordern.\n</li><li>Die Initialisierungsreihenfolge durch <code>EcuM</code> (<code>V2xM</code> vor <code>V2xGn</code>, <code>V2xFac</code> und <code>V2xBtp</code>) ist einzuhalten.\n</li><li>Implementierer müssen sicherstellen, dass die Signaturen der Init-Funktionen generische Konfigurationszeiger (<code>const void *</code> bzw. <code>void*</code>) verwenden und der Abruf der Referenzzeit der Signatur <code>V2xM_GetRefTimePtr(Std_ReturnType, uint32** const*)</code> entspricht.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-52b1e9069b69454a", "to": "FIG-e9e4b351be752ca4", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Parameter von <code>V2xM_Init</code> von <code>const V2xM_ConfigType*</code> zu <code>const void *</code> geändert.\n</li><li>Parameter von <code>V2xGn_Init</code> von void (kein Parameter) zu <code>const void *</code> geändert.\n</li><li>Parameter von <code>V2xFac_Init</code> von void (kein Parameter) zu <code>const void *</code> geändert.\n</li><li>Parameter von <code>V2xBtp_Init</code> von void (kein Parameter) zu <code>void*</code> geändert.\n</li><li>Parameterliste / Signaturdarstellung von <code>V2xM_GetRefTimePtr</code> von <code>(Std_ReturnType, uint32** const)</code> zu <code>(Std_ReturnType, uint32** const*)</code> geändert.\n</li></ul>"}, {"from": "FIG-e9e4b351be752ca4", "to": "FIG-85bc6c5cfdb31b0d", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
